<script>
  import { base } from '$app/paths';
  import report from '$lib/generated/report.json';
  let unit = $state('providers');
  let status = $state('Certified');
  let basis = $state('historical');
  let query = $state('');
  let pathway = $state('All pathways');
  let evidence = $state('All evidence');
  let listing = $state('All listed');
  let year = $state('All years');
  let page = $state(1);
  const pathways = ['Rev5', '20x Pilot', '20x'];
  const labels = {'documented-small':'Documented small','likely-small':'Likely small','documented-not-small':'Documented other-than-small','likely-not-small':'Likely other-than-small',unknown:'Unknown'};
  const pct = n => n == null ? '—' : `${n.toFixed(1)}%`;
  const count = n => n.toLocaleString('en-US');
  const share = (n,total) => total ? n / total * 100 : 0;
  const reset = () => { page = 1; };
  let current = $derived(report.reports.groups.filter(r=>r.unit===unit && r.status===status && pathways.includes(r.pathway)));
  let annual = $derived(report.reports.annual.filter(r=>r.unit===unit && r.basis===basis && r.pathway==='All pathways'));
  let windows = $derived(report.reports.windows.filter(r=>r.unit===unit && r.basis===basis && r.pathway==='All pathways'));
  let filtered = $derived(report.offerings.filter(o=>!o.excluded && (listing==='All records'||listing==='All listed'&&o.currentListed||listing==='Certified'&&o.currentCertified||listing==='Initial Implementation'&&o.status===listing||listing==='Delisted'&&o.status==='No Status Found (Delisted)') && (pathway==='All pathways'||o.pathway===pathway) && (evidence==='All evidence'||o.currentAssessment.classification===evidence) && (year==='All years'||o.firstCertification?.transition_date.startsWith(year)) && `${o.name} ${o.providerName} ${o.id}`.toLowerCase().includes(query.toLowerCase())));
  let pages = $derived(Math.max(1,Math.ceil(filtered.length/30)));
  let visible = $derived(filtered.slice((page-1)*30,page*30));
  const years = [...new Set(report.reports.annual.map(r=>r.year))].reverse();
  const safeUrl = url => typeof url==='string' && /^https?:\/\//i.test(url) ? url : undefined;
</script>

<svelte:head>
  <title>Small business in the FedRAMP Marketplace</title>
  <meta name="description" content="An independent, reproducible study of small business participation in FedRAMP Rev5 and 20x, with provider-level sources and explicit evidence gaps." />
</svelte:head>
<a class="skip" href="#main">Skip to content</a>
<header class="header"><div class="wrap masthead"><a class="brand" href="{base}/" aria-label="Marketplace small business home"><svg width="26" height="28" viewBox="0 0 26 28" aria-hidden="true"><path fill="currentColor" d="M0 17h6v11H0zM10 9h6v19h-6zM20 0h6v28h-6z"/></svg><span>Marketplace<br/><strong>Small business</strong></span></a><nav aria-label="Main navigation"><a href="#participation">Findings</a><a href="#evidence">Evidence</a><a href="{base}/methodology/">Methodology</a><a href="#downloads">Data ↓</a></nav></div></header>
<main id="main" class="wrap">
  <section class="hero" aria-labelledby="title"><div><p class="eyebrow">An independent research project · Updated {report.asOf}</p><h1>Who gets access<br/>to the federal cloud?</h1><p class="intro">Small business participation in the FedRAMP Marketplace, across Rev5, the 20x pilot, and the 20x program.</p><p>Explore the companies behind the products, the evidence of their size, and what certification trends can—and cannot—tell us.</p><a class="rule-link" href="#participation">Explore the findings <span aria-hidden="true">↓</span></a></div><aside class="hero-aside"><p class="eyebrow">The finding so far</p><h2>Participation is visible.<br/>The change in access is harder to establish.</h2><p>Public records document small-business representations for <strong>{report.coverage.current.documentedSmall} of {report.coverage.current.total}</strong> currently listed, identifiable commercial providers ({pct(report.coverage.current.documentedPct)}).</p><p>Historical size is unknown for <strong>{pct(report.coverage.historical.unknownPct)}</strong> of providers in first-certification cohorts. These data alone cannot show that recent reforms caused access to improve.</p><a href="{base}/methodology/#limitations">Understand the evidence gaps ↗</a></aside></section>
  <div class="finding"><strong>Read the percentages as evidence coverage, not a complete census of small businesses.</strong> “Documented small” means a matched public size representation in a relevant NAICS context. Unknown companies remain in every denominator. A zero means no qualifying evidence was found.</div>

  <section id="participation" aria-labelledby="participation-title"><div class="section-head"><div><p class="eyebrow">01 / The current picture</p><h2 id="participation-title">Rev5 and 20x, side by side</h2></div><p>Current size evidence · current pathway and status</p></div><div class="controls"><label><span>Count</span><select bind:value={unit}><option value="providers">Distinct providers</option><option value="offerings">Product / package listings</option></select></label><label><span>Marketplace status</span><select bind:value={status}><option>Certified</option><option>Initial Implementation</option><option>All listed</option><option>Other pre-certification</option><option>Delisted</option></select></label></div>
    <div class="legend"><span><i class="swatch"></i>Documented small</span><span><i class="swatch likely"></i>Likely small</span><span><i class="swatch other"></i>Other-than-small evidence</span><span><i class="swatch unknown"></i>Unknown</span></div>
    {#each current as row (row.pathway)}<div class="chart-row"><div class="chart-label"><strong>{row.pathway==='20x'?'20x · non-pilot':row.pathway}</strong><small>{count(row.total)} {unit}</small></div><div class="bar" role="img" aria-label={`${row.pathway}: ${row.documentedSmall} documented small, ${row.counts['likely-small']} likely small, ${row.counts.unknown} unknown, out of ${row.total}`}><span class="documented" style:width="{share(row.documentedSmall,row.total)}%"></span><span class="likely" style:width="{share(row.counts['likely-small'],row.total)}%"></span><span class="other" style:width="{share(row.counts['documented-not-small']+row.counts['likely-not-small'],row.total)}%"></span><span class="unknown" style:width="{share(row.counts.unknown,row.total)}%"></span></div><div class="chart-value">{pct(row.documentedPct)}<small>documented</small></div></div>{/each}
    <div class="table-scroll"><table><caption>{status}: small business evidence, including unknowns in the denominator</caption><thead><tr><th scope="col">Pathway</th><th scope="col">Total {unit}</th><th scope="col">Documented small</th><th scope="col">Including likely small</th><th scope="col">Unknown</th></tr></thead><tbody>{#each current as r (r.pathway)}<tr><th scope="row">{r.pathway==='20x'?'20x · non-pilot':r.pathway}</th><td>{r.total}</td><td>{r.documentedSmall} <small>({pct(r.documentedPct)})</small></td><td>{r.expandedSmall} <small>({pct(r.expandedPct)})</small></td><td>{r.counts.unknown} <small>({pct(r.unknownPct)})</small></td></tr>{/each}</tbody></table></div>
    <p class="note">Providers may appear in multiple pathways, so rows do not sum to a distinct-provider total. “Certified” includes certified offerings in remediation. Initial implementation is preparation, not certification. The source distinguishes “20x Pilot” from “20x”; pilot history is also retained in the downloads.</p>
  </section>

  <section id="trends" aria-labelledby="trends-title"><div class="section-head"><div><p class="eyebrow">02 / A view over time</p><h2 id="trends-title">Who was certified each year?</h2></div><p>First observed certification per product / package</p></div><div class="controls"><label><span>Size evidence</span><select bind:value={basis}><option value="historical">At certification · historical evidence</option><option value="current">Today · current evidence applied to cohorts</option></select></label></div><p class="unit-note">Counting {unit}. {basis==='historical'?'Historical evidence is limited; current registrations are never projected backward.':'This alternative describes the current size of past cohorts. It does not describe size when they were certified.'} For providers, use their earliest product certification within each cohort.</p>
    <div class="year-bars">{#each annual as r (r.year)}<div class="chart-row"><div class="chart-label"><strong>{r.year}{r.partial?'*':''}</strong><small>n = {r.total}</small></div><div class="bar" role="img" aria-label={`${r.year}: ${r.documentedSmall} documented small, ${r.counts['likely-small']} likely small, ${r.counts.unknown} unknown, out of ${r.total}`}><span class="documented" style:width="{share(r.documentedSmall,r.total)}%"></span><span class="likely" style:width="{share(r.counts['likely-small'],r.total)}%"></span><span class="other" style:width="{share(r.counts['documented-not-small']+r.counts['likely-not-small'],r.total)}%"></span><span class="unknown" style:width="{share(r.counts.unknown,r.total)}%"></span></div><div class="chart-value">{r.expandedSmall} / {r.total}<small>{pct(r.expandedPct)} incl. likely</small></div></div>{/each}</div>
    <details><summary>Annual counts and percentages</summary><div class="table-scroll"><table><caption>Annual certification cohorts · {basis} size · {unit}</caption><thead><tr><th scope="col">Year</th><th scope="col">Total</th><th scope="col">Documented small</th><th scope="col">Including likely small</th><th scope="col">Unknown</th><th scope="col">First-time providers</th></tr></thead><tbody>{#each annual as r (r.year)}<tr><th scope="row">{r.year}{r.partial?'*':''}</th><td>{r.total}</td><td>{r.documentedSmall} ({pct(r.documentedPct)})</td><td>{r.expandedSmall} ({pct(r.expandedPct)})</td><td>{r.counts.unknown}</td><td>{r.firstTimeProviders}</td></tr>{/each}</tbody></table></div></details><p class="note">* {report.asOf.slice(0,4)} is a partial year through {report.asOf}. Source history is retrospective; “first-time” means first observed in these records, not proven first-ever participation. Historical pathways are the pathway recorded at certification, not necessarily today’s pathway.</p>
    <div class="callout"><h3>The latest 24 months<br/>versus the previous 24</h3><div><p>Equal-length windows make the comparison more useful than comparing a partial year with a complete one. They still do not control for pilot selection, impact level, policy timing, or missing historical evidence.</p><div class="table-scroll"><table><caption>{basis==='historical'?'Size at certification':'Current size of certification cohorts'} · {unit}</caption><thead><tr><th scope="col">Window</th><th scope="col">Total</th><th scope="col">Small, including likely</th><th scope="col">Unknown</th></tr></thead><tbody>{#each windows as r (r.label)}<tr><th scope="row">{r.label}<small>{r.start} to {new Date(Date.parse(r.endExclusive)-86400000).toISOString().slice(0,10)}</small></th><td>{r.total}</td><td>{r.expandedSmall} ({pct(r.expandedPct)})</td><td>{r.counts.unknown} ({pct(r.unknownPct)})</td></tr>{/each}</tbody></table></div><p class="note">No causal conclusion: different evidence coverage can change the observed small-business share without any change in actual access.</p></div></div>
  </section>

  <section id="evidence" aria-labelledby="evidence-title"><div class="section-head"><div><p class="eyebrow">03 / Inspect the evidence</p><h2 id="evidence-title">Every product. Every assessment.</h2></div><a href="{base}/downloads/providers.csv" download>Download provider data ↓</a></div><p>Open a record for its reasoning and source links. The size classification belongs to the provider; product records retain separate status, pathway, and certification history.</p><div class="controls"><label class="control-search"><span>Search provider, product, or package ID</span><input type="search" bind:value={query} oninput={reset} placeholder="e.g. InfusionPoints" /></label><label><span>Pathway</span><select bind:value={pathway} onchange={reset}><option>All pathways</option>{#each pathways as p (p)}<option>{p}</option>{/each}<option>Unknown</option></select></label><label><span>Status</span><select bind:value={listing} onchange={reset}><option>All listed</option><option>Certified</option><option>Initial Implementation</option><option>Delisted</option><option>All records</option></select></label><label><span>Current size evidence</span><select bind:value={evidence} onchange={reset}><option>All evidence</option>{#each Object.entries(labels) as [key,label] (key)}<option value={key}>{label}</option>{/each}</select></label><label><span>First certification year</span><select bind:value={year} onchange={reset}><option>All years</option>{#each years as y (y)}<option>{y}</option>{/each}</select></label></div>
    <p class="coverage-line" aria-live="polite">{count(filtered.length)} matching product records · showing {filtered.length?((page-1)*30)+1:0}–{Math.min(page*30,filtered.length)}</p>
    <div class="table-scroll"><table class="evidence-table"><caption>Provider and product evidence · government-operated services excluded</caption><thead><tr><th scope="col">Provider / product</th><th scope="col">Pathway / status</th><th scope="col">Current size / confidence</th><th scope="col">Reason &amp; sources</th></tr></thead><tbody>{#each visible as o (o.id)}<tr><th scope="row">{o.providerName}<small>{o.name||'Product name unavailable'}</small><small>{o.id} · {o.certClass}</small></th><td>{o.pathway}<small>{o.status}</small>{#if o.everPilot&&!o.pilot}<small>Previously in pilot</small>{/if}</td><td><span class="badge {o.currentAssessment.classification}">{labels[o.currentAssessment.classification]}</span><small>{o.currentAssessment.confidence} confidence</small></td><td><details><summary>View assessment</summary><p>{o.currentAssessment.reason}</p>{#if o.currentAssessment.evidence.length}<ul>{#each o.currentAssessment.evidence as e,i (i)}<li><a href={safeUrl(e.url)} target="_blank" rel="noreferrer">{e.kind}</a>{#if e.legalName}<br/>{e.legalName}{/if}{#if e.primaryNaics}<br/>Primary NAICS: {e.primaryNaics}{/if}{#if e.uei}<br/>UEI: {e.uei}{/if}</li>{/each}</ul>{:else}<p>No qualifying source found. Registry and website searches were attempted for every resolved provider; the research log is in the repository.</p>{/if}<p><strong>At first certification:</strong> {o.firstCertification?.transition_date.slice(0,10)??'No event recorded'} · {labels[o.historicalAssessment.classification]}</p><p>{o.historicalAssessment.reason}</p>{#each o.historicalAssessment.evidence as e,i (i)}<p><a href={safeUrl(e.url)} target="_blank" rel="noreferrer">Historical source: {e.kind}</a></p>{/each}<p>Marketplace flag: {o.marketplaceFlags.join(', ')||'Not supplied'}. Retained as a separate source field, not a legal finding.</p></details></td></tr>{/each}</tbody></table></div>{#if !filtered.length}<p class="empty">No records match these filters. Try a broader search or select all evidence.</p>{/if}<div class="pagination"><button disabled={page===1} onclick={()=>page--}>← Previous</button><span>Page {page} of {pages}</span><button disabled={page===pages} onclick={()=>page++}>Next →</button></div>
  </section>

  <section id="downloads" aria-labelledby="downloads-title"><div class="section-head"><div><p class="eyebrow">04 / Reuse and extend</p><h2 id="downloads-title">The data behind the page</h2></div><a href="https://github.com/pete-wai/marketplace-smb">View the repository ↗</a></div><div class="twocol"><div><h3>A reproducible snapshot</h3><p>{count(report.coverage.offerings)} package identities and {count(report.coverage.providers)} resolved provider identities, including historical and delisted records. Every resolved provider was screened against public SBA search and its listed websites.</p><p class="note">{report.coverage.unresolvedIdentityOfferings} package identities could not be linked to a provider in retrieved exports, including {report.coverage.current.unresolvedIdentityOfferings} currently listed records. They remain in product totals. {report.coverage.excludedProviders} government operators ({report.coverage.excludedOfferings} products) are excluded from commercial participation rates.</p><a href="https://github.com/FedRAMP/marketplace-fedramp-gov-data/tree/{report.source.commit}">Marketplace source snapshot · {report.source.commit.slice(0,7)} ↗</a></div><div class="download-list">{#each [['analysis.json','Complete dataset · JSON'],['providers.csv','Providers and evidence · CSV'],['offerings.csv','Products and historical assessments · CSV'],['groups.csv','Current pathway and status comparisons · CSV'],['annual.csv','Annual certification cohorts · CSV'],['windows.csv','Rolling 24-month comparisons · CSV'],['classes.csv','Certification class breakdown · CSV'],['marketplaceFlags.csv','Original Marketplace flags · CSV'],['status-events.csv','All status transitions · CSV']] as [file,label] (file)}<a href="{base}/downloads/{file}" download>{label}<span aria-hidden="true">↓</span></a>{/each}</div></div></section>
</main>
<footer><div class="wrap"><p><strong>Marketplace / Small business</strong><br/>Independent research. Not an official FedRAMP or SBA determination.</p><p><a href="{base}/methodology/">Definitions, methods &amp; limitations</a><br/><a href="https://github.com/pete-wai/marketplace-smb/issues">Suggest a correction or additional evidence ↗</a></p></div></footer>
